[CmdletBinding()]
param([string]$ProjectRoot)
$ErrorActionPreference='Stop';if([string]::IsNullOrWhiteSpace($ProjectRoot)){$ProjectRoot=(Get-Location).Path};$p=Join-Path $ProjectRoot 'ES/Automation/Contracts/es-ai-abc-engineering-competition-result-v1.schema.json';$s=Get-Content -Raw -Encoding UTF8 -LiteralPath $p|ConvertFrom-Json;$required=@($s.properties.evidenceSummary.required);$repair=$s.properties.evidenceSummary.properties.repairReceipts;$repairRequired=@($repair.items.required);$ok=(@('independentReplayVerifiedCount','providerScoreComparisonStatus','repairReceipts')|ForEach-Object{$_ -in $required}) -notcontains $false;$repairBound=($repair.minItems -ge 2 -and 'architectureId' -in $repairRequired -and 'status' -in $repairRequired -and 'attempts' -in $repairRequired -and $repair.items.properties.status.const -eq 'completed');$pass=($s.additionalProperties -eq $false -and $ok -and $repairBound -and $s.properties.evidenceSummary.additionalProperties -eq $false);$state='failed';if($pass){$state='passed'};[pscustomobject]@{status=$state;strictTopLevel=$s.additionalProperties -eq $false;independentReplayBound='independentReplayVerifiedCount' -in $required;providerStabilityBound='providerScoreComparisonStatus' -in $required;repairReceiptBound=$repairBound};if(-not $pass){exit 1} 
